import { AbstractInputField } from '../shared/abstract-input-field';
import './neon-number-field.scss';
import { createElement, dynamicAttr, dynamicProperty, updateDynamicAttribute, updateDynamicProperty, useElementIfElse } from '../shared/dom-manipulation';
import { deLocalizeNumber, localizeNumber } from '@ps-refarch-ux/mfe-utils';
import { getBasicNumberValidationRules, getNumberValidators } from '../shared/validation-engine/validate-engine';
export class NeonNumberField extends AbstractInputField {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-number-field';
    }
    static get observedAttributes() {
        return super.observedAttributes.concat([
            'data-placeholder-text',
            'autocomplete',
            'data-is-integer',
            'data-min-length',
            'data-max-length',
            'data-min-value',
            'data-max-value',
            'data-min-value-exclusive',
            'data-max-value-exclusive',
            'data-max-decimals'
        ]);
    }
    generateValidationRules() {
        const validationRules = getBasicNumberValidationRules();
        validationRules.setProperty('isRequired', this.getAttribute('data-is-required'), Boolean);
        validationRules.setProperty('isInteger', this.getAttribute('data-is-integer'), Boolean);
        validationRules.setProperty('minLength', this.getAttribute('data-min-length'), Number);
        validationRules.setProperty('maxLength', this.getAttribute('data-max-length'), Number);
        validationRules.setProperty('minValue', this.getAttribute('data-min-value'), Number);
        validationRules.setProperty('maxValue', this.getAttribute('data-max-value'), Number);
        validationRules.setProperty('minValueExclusive', this.getAttribute('data-min-value-exclusive'), Number);
        validationRules.setProperty('maxValueExclusive', this.getAttribute('data-max-value-exclusive'), Number);
        validationRules.setProperty('maxDecimals', this.getAttribute('data-max-decimals'), Number);
        this.validators = getNumberValidators(validationRules);
        this.addCustomValidateToValidators();
    }
    setValue(value, skip) {
        if (value == null) {
            value = '';
        }
        const inputEl = this.inputElement;
        if (inputEl != null && value !== inputEl.value) {
            inputEl.value = value;
        }
        if (skip !== true) {
            this.setModelValue(deLocalizeNumber(value), true);
        }
    }
    validateModelValueType(modelValue) {
        if (typeof modelValue === 'number') {
            return modelValue;
        }
        return undefined;
    }
    //NOTE: This function should look almost identical to what is in neon-date-field and neon-time-field
    setModelValue(modelValue, skip) {
        if (this.modelValue == null && modelValue == null) {
            return false;
        }
        const ele = this.inputElement;
        if (modelValue !== ele.modelValue) {
            ele.modelValue = modelValue;
            if (skip !== true) {
                this.setValue(localizeNumber(modelValue), true);
            }
            return true;
        }
        return false;
    }
    renderInputElement() {
        return createElement('input', {
            attrs: {
                id: dynamicAttr(() => { return this.getInputId(); }),
                type: 'text',
                'aria-label': dynamicAttr(() => { return this.getAriaLabelForInput(); }),
                autocomplete: dynamicAttr(() => { return this.getAttribute('autocomplete'); }),
                placeholder: dynamicAttr(() => { return this.getAttribute('data-placeholder-text'); })
            },
            properties: {
                disabled: dynamicProperty(() => { return this.getDisabledStatus(); })
            },
            listeners: {
                'input': (event) => { this.inputChange(); },
                'blur': (event) => { return this.focusLost(event); }
            }
        });
    }
    renderContent() {
        return [createElement('div', {
                attrs: {
                    class: dynamicAttr(() => { return 'neon-number-field-input-container neon-input-field-first' + this.getSizeClass(); })
                },
            }, ...useElementIfElse(() => { return this.getAttribute('data-is-read-only') === 'true'; }, () => { return this.readOnlyElement; }, () => { return this.inputElement; }))
        ];
    }
    attributeChanged(attribute, oldValue, newValue) {
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        super.attributeChanged(attribute, oldValue, newValue);
        switch (attribute) {
            case 'autocomplete':
                updateDynamicAttribute(this, 'autocomplete');
                break;
            case 'data-placeholder-text':
                updateDynamicAttribute(this, 'placeholder');
                break;
            case 'data-is-read-only':
                updateDynamicProperty(this, 'disabled');
                break;
        }
    }
}
